add_filter( 'woocommerce_product_add_to_cart_text', 'perfectpixel_atc_label_by_category', 30, 2 );

function perfectpixel_atc_label_by_category( $text, $product ) {
	if ( ! $product || $product->is_type( 'external' ) ) {
		return $text;
	}
	if ( 'woocommerce_product_add_to_cart_text' === current_filter() && ! ( $product->is_type( 'simple' ) && $product->is_purchasable() && $product->is_in_stock() ) ) {
		return $text;
	}
	foreach ( explode( '|', '{{atc_labels_by_category}}' ) as $pair ) {
		$parts = array_map( 'trim', explode( '=', $pair, 2 ) );
		if ( 2 === count( $parts ) && absint( $parts[0] ) && '' !== $parts[1] && has_term( absint( $parts[0] ), 'product_cat', $product->get_id() ) ) {
			return $parts[1];
		}
	}
	return $text;
}
